class Solution {
public:
    vector<int> sumAndMultiply(string s, vector<vector<int>>& queries) {
        const long long MOD = 1000000007LL;
        int n = s.size();
        vector<long long> cnt(n + 1, 0), digSum(n + 1, 0), P(n + 1, 0), pw(n + 1, 1);
        for (int i = 0; i < n; i++) {
            cnt[i + 1] = cnt[i];
            digSum[i + 1] = digSum[i];
            P[i + 1] = P[i];
            pw[i + 1] = pw[i];
            int d = s[i] - '0';
            if (d != 0) {
                cnt[i + 1]++;
                digSum[i + 1] += d;
                P[i + 1] = (P[i] * 10 + d) % MOD;
                pw[i + 1] = (pw[i] * 10) % MOD;
            }
        }
        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& q : queries) {
            int l = q[0], r = q[1];
            long long k = cnt[r + 1] - cnt[l];
            if (k == 0) { ans.push_back(0); continue; }
            long long x = (P[r + 1] - P[l] * pw[k] % MOD + MOD) % MOD;
            long long sum = digSum[r + 1] - digSum[l];
            ans.push_back((int)(x * sum % MOD));
        }
        return ans;
    }
};
